package ai.decisionos.aside;
import android.content.*;import android.webkit.CookieManager;import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.concurrent.*;
/** Serial, bounded, same-origin downloads. Auth headers never follow redirects. */
final class BlackboardDownloads {
 static final ExecutorService WORK=Executors.newSingleThreadExecutor();
 static boolean allowed(String url){try{URI u=new URI(url);return "https".equals(u.getScheme())&&"blackboard.unist.ac.kr".equals(u.getHost())&&u.getUserInfo()==null&&(u.getPort()==-1||u.getPort()==443);}catch(Exception e){return false;}}
 static void start(Context context,JSONArray files,Runnable updated){Context app=context.getApplicationContext();if(files.length()>100)throw new IllegalArgumentException("한 번에 100개까지 다운로드할 수 있어요.");for(int n=0;n<files.length();n++){JSONObject f=files.optJSONObject(n);if(f==null||!allowed(f.optString("url")))throw new IllegalArgumentException("현재 Blackboard에서 확인한 자료만 다운로드할 수 있어요.");}
  final String batch=java.util.UUID.randomUUID().toString();final long[] total={0};
  for(int n=0;n<files.length();n++){final JSONObject file=files.optJSONObject(n);final String id=java.util.UUID.randomUUID().toString(),cookie=CookieManager.getInstance().getCookie(file.optString("url"));JSONObject initial=new JSONObject();GoalStore.put(initial,"id",id);GoalStore.put(initial,"batch",batch);GoalStore.put(initial,"name",file.optString("name"));GoalStore.put(initial,"state","queued");try(CampusFlowStore s=new CampusFlowStore(app)){s.save("bb_downloads",initial);}WORK.execute(()->{JSONObject result=new JSONObject();GoalStore.put(result,"id",id);GoalStore.put(result,"batch",batch);GoalStore.put(result,"name",file.optString("name"));File temp=null;HttpURLConnection c=null;try{if(app.getSharedPreferences("bb_cancel",0).getBoolean(batch,false))throw new IOException("취소됨");if(total[0]>=200L*1024*1024)throw new IOException("일괄 다운로드 200MiB 제한");c=(HttpURLConnection)new URL(file.getString("url")).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(30000);if(cookie!=null)c.setRequestProperty("Cookie",cookie);int code=c.getResponseCode();if(code!=200)throw new IOException("HTTP "+code+" · 리다이렉트나 재인증이 필요하면 원문에서 확인해 주세요.");String type=c.getContentType();if(type!=null&&type.toLowerCase(java.util.Locale.ROOT).contains("text/html"))throw new IOException("로그인/HTML 화면은 자료로 저장하지 않아요.");if(c.getContentLengthLong()>50L*1024*1024)throw new IOException("파일 50MiB 제한");File dir=new File(app.getFilesDir(),"documents");dir.mkdirs();temp=File.createTempFile("bb-",".part",dir);MessageDigest digest=MessageDigest.getInstance("SHA-256");long bytes=0;try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(temp)){byte[] b=new byte[32768];int count;while((count=in.read(b))!=-1){if(app.getSharedPreferences("bb_cancel",0).getBoolean(batch,false))throw new IOException("취소됨");bytes+=count;total[0]+=count;if(bytes>50L*1024*1024||total[0]>200L*1024*1024)throw new IOException("다운로드 용량 제한");digest.update(b,0,count);out.write(b,0,count);}}StringBuilder hash=new StringBuilder();for(byte v:digest.digest())hash.append(String.format(java.util.Locale.ROOT,"%02x",v&255));String name=file.optString("name","").toLowerCase(java.util.Locale.ROOT);String ext=name.matches(".*\\.(pdf|ppt|pptx|doc|docx|hwp|hwpx|xls|xlsx|zip)$")?name.substring(name.lastIndexOf('.')+1):type!=null&&type.contains("pdf")?"pdf":"bin";File target=new File(dir,hash+"."+ext);if(target.exists()){temp.delete();}else if(!temp.renameTo(target))throw new IOException("파일 저장 실패");GoalStore.put(result,"state","downloaded");GoalStore.put(result,"filename",target.getName());GoalStore.put(result,"sha256",hash.toString());GoalStore.put(result,"bytes",bytes);}catch(Exception e){if(temp!=null)temp.delete();GoalStore.put(result,"state","failed");GoalStore.put(result,"reason",e instanceof IOException?e.getMessage():"자료 저장 실패");}finally{if(c!=null)c.disconnect();try(CampusFlowStore s=new CampusFlowStore(app)){s.save("bb_downloads",result);}if(updated!=null)new android.os.Handler(android.os.Looper.getMainLooper()).post(updated);}});}
 }
 static void cancel(Context c,String batch){c.getSharedPreferences("bb_cancel",0).edit().putBoolean(batch,true).apply();}
}
